alter table public.account_deletion_jobs add column lease_token uuid,add column lease_until timestamptz;
create function public.claim_account_deletion(p_user uuid,p_token uuid) returns boolean language plpgsql security definer set search_path='' as $$ begin if p_token is null then return false;end if;update public.account_deletion_jobs set lease_token=p_token,lease_until=clock_timestamp()+interval '15 minutes' where user_id=p_user and (lease_until is null or lease_until<clock_timestamp());return found;end $$;
create function public.check_account_deletion_lease(p_user uuid,p_token uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.account_deletion_jobs where user_id=p_user and lease_token=p_token and lease_until>clock_timestamp()) $$;
revoke all on function public.claim_account_deletion(uuid,uuid),public.check_account_deletion_lease(uuid,uuid) from public;grant execute on function public.claim_account_deletion(uuid,uuid),public.check_account_deletion_lease(uuid,uuid) to service_role;
